import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.X4qO_DBC.js";const g=JSON.parse('{"title":"企业级高级筛选与 AI 智能搭建 · 背诵版","description":"","frontmatter":{},"headers":[],"relativePath":"_面试材料/高级筛选与AI智能搭建-背诵版.md","filePath":"_面试材料/高级筛选与AI智能搭建-背诵版.md","lastUpdated":1794251976000}'),s={name:"_面试材料/高级筛选与AI智能搭建-背诵版.md"};function r(d,e,l,i,p,c){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="企业级高级筛选与-ai-智能搭建-·-背诵版" tabindex="-1">企业级高级筛选与 AI 智能搭建 · 背诵版 <a class="header-anchor" href="#企业级高级筛选与-ai-智能搭建-·-背诵版" aria-label="Permalink to &quot;企业级高级筛选与 AI 智能搭建 · 背诵版&quot;">​</a></h1><p>用途：回答“介绍一下这个项目”“你在这个项目中解决了什么问题”“AI 结果如何进入原有业务系统”。建议先背第一部分的 2—3 分钟版本，再按追问展开。</p><h2 id="一句话先说清楚" tabindex="-1">一句话先说清楚 <a class="header-anchor" href="#一句话先说清楚" aria-label="Permalink to &quot;一句话先说清楚&quot;">​</a></h2><p><strong>这是一个把自然语言生成的筛选条件接入存量企业检索系统的复杂业务模块，核心是处理条件归属、配置时序、双视图查询和长任务生命周期。</strong></p><p>完整链路可以先记成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>自然语言输入</span></span>
<span class="line"><span>  → POST SSE 生成任务</span></span>
<span class="line"><span>  → ready 条件校验</span></span>
<span class="line"><span>  → 条件快照回填</span></span>
<span class="line"><span>  → 配置就绪后转换</span></span>
<span class="line"><span>  → 卡片 / 表格查询</span></span>
<span class="line"><span>  → 人工调整、保存和分享</span></span></code></pre></div><p>本稿基于以下源码核对：</p><ul><li><code>C:/Users/24060/Desktop/项目/tungee/sales/app/containers/CustomerSeekingPage/containers/AdvancedFilter/containers/EnterpriseFilter.js</code></li><li><code>C:/Users/24060/Desktop/项目/tungee/sales/app/containers/CustomerSeekingPage/containers/AdvancedFilter/components/SmartBuilder/index.js</code></li><li><code>C:/Users/24060/Desktop/项目/tungee/sales/app/containers/CustomerSeekingPage/containers/AdvancedFilter/components/SmartBuilder/taskSession.js</code></li><li><code>C:/Users/24060/Desktop/项目/tungee/sales/app/containers/CustomerSeekingPage/containers/AdvancedFilter/api.js</code></li><li><code>C:/Users/24060/Desktop/项目/tungee/sales/app/containers/CustomerSeekingPage/containers/AdvancedFilter/utils.js</code></li><li><code>C:/Users/24060/Desktop/项目/tungee/sales/app/components/DimensionSelector/index.js</code></li></ul><p>文中标记含义：</p><ul><li><strong>【代码已证实】</strong>：可以直接从源码说明。</li><li><strong>【本人已确认】</strong>：需要你确认后，才能使用“我设计”“我独立解决”等表述。</li><li><strong>【合理推测】</strong>：用于解释简单替代方案的风险，不能当作历史事实。</li><li><strong>【缺少证据】</strong>：当前材料没有线上指标、历史实现或个人职责证据。</li></ul><hr><h2 id="一、先记住这句话" tabindex="-1">一、先记住这句话 <a class="header-anchor" href="#一、先记住这句话" aria-label="Permalink to &quot;一、先记住这句话&quot;">​</a></h2><p><strong>我参与的是一个把自然语言生成结果接入企业高级筛选系统的复杂业务模块，重点解决 AI 任务、筛选器配置、双视图结果和页面生命周期同时变化时，条件归属和查询结果保持一致的问题。</strong></p><p>面试官继续追问时，围绕三个词展开：</p><ol><li><strong>条件归属</strong>：普通筛选和智能搭建的条件要分开保存。</li><li><strong>条件一致</strong>：界面回填的条件和实际查询提交的条件要来自同一份快照。</li><li><strong>任务生命周期</strong>：流连接、后端任务和页面缓存是不同层次，不能混为一谈。</li></ol><hr><h2 id="二、2—3-分钟口述版本" tabindex="-1">二、2—3 分钟口述版本 <a class="header-anchor" href="#二、2—3-分钟口述版本" aria-label="Permalink to &quot;二、2—3 分钟口述版本&quot;">​</a></h2><p>面试官您好，我介绍一下企业级高级筛选与 AI 智能搭建项目。</p><p>这个项目面向企业客户检索场景。用户原来需要在高级筛选页面里逐项选择行业、地区、规模等条件，再查看企业结果。项目增加智能搭建后，用户可以直接用自然语言描述目标客户，系统通过 AI 生成筛选条件，然后继续使用原来的条件编辑、企业查询、保存条件组和分享能力。</p><p>它和普通 CRUD 页面相比，复杂点不在于多几个表单字段，而在于多个异步过程会同时发生：AI 条件生成是一个持续返回阶段事件的长任务；筛选维度配置也是异步加载的；页面还同时支持普通筛选和智能搭建，以及卡片和表格两种结果视图。用户还可能在任务执行中离开页面、切换主体或切换结果视图。</p><p>我先讲一次完整流程。用户输入自然语言后，前端通过 <code>streamAdvancedFilterAgentBuild</code> 使用 POST Fetch 接收 SSE 流。读取响应时，先用 <code>TextDecoder</code> 做增量解码，再用字符串缓冲按照空行拆分 SSE 帧，解析阶段、结果和错误事件。任务执行过程中，页面展示阶段进度，并保存服务端返回的 <code>taskId</code>。</p><p>当任务返回 ready 状态并且存在有效的条件对象时，前端才把结果交给筛选系统。这里不会直接把结果塞进某个组件，而是通过 <code>applyFilterSnapshot</code> 统一更新容器里的条件、关系和值回填，再把同一份条件快照传给 <code>handleFilterSnapshotSearch</code> 发起查询。这样可以减少 React 状态更新还没有完成时，查询读取到旧条件的风险。</p><p>条件回填还有一个时序问题。<code>DimensionSelector</code> 需要先拿到维度配置，才能把接口格式转换成界面可以编辑的结构。如果 AI 结果先返回，配置还没有加载完成，代码会先把值放进 <code>pendingValue</code>；等配置到达后，再优先转换这份待回填值，避免空的默认值把 AI 条件覆盖掉。关系值还要区分 0 和 1，不能简单用真假值判断。</p><p>在结果展示上，卡片和表格分别保存自己的数据、分页、loading、是否查询过以及查询键。切换视图时，前端会根据筛选条件、关系、分页、排序和模式生成查询键；如果目标视图已有相同查询键的结果，就可以复用，否则再请求。用户在请求进行中再次修改条件时，当前实现只保留最新一份待查条件，等正在进行的查询结束后继续执行。</p><p>长任务方面，普通页面会按用户和主体保存 <code>taskId</code>、输入文本、开始时间和阶段快照。用户在有效期内返回时，可以带着同一个 <code>taskId</code> 重新连接，并直接展示已经完成的阶段。任务有效期是从开始时间计算的五分钟。嵌入到其他宿主的场景会关闭这套页面缓存，避免不同宿主之间复用错误任务。</p><p>请求控制上，<code>AbortController</code> 负责取消旧的流连接，<code>requestId</code> 负责判断回调是否仍属于当前这次执行。因为取消连接不代表已经进入 JavaScript 回调队列的代码一定不会继续执行，所以两者解决的是资源释放和结果提交资格两个不同问题。</p><p>我在这个项目中重点参与了高级筛选和智能搭建相关的前端开发，具体负责范围需要结合实际改动进一步确认。代码层面可以确认的是：项目已经形成了从自然语言输入、流式生成、条件回填，到企业查询、人工编辑、保存和分享的完整前端链路。没有线上埋点或对比数据时，我会把收益表述为“形成了可复用、可追踪的闭环”，不会编造效率提升比例。</p><hr><h2 id="三、完整数据流" tabindex="-1">三、完整数据流 <a class="header-anchor" href="#三、完整数据流" aria-label="Permalink to &quot;三、完整数据流&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>自然语言输入</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>SmartBuilder.handleBuild</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>POST Fetch + ReadableStream</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>TextDecoder 增量解码</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>SSE 缓冲分帧与事件解析</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>阶段事件 / ready 结果 / error</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>检查 ready + filter_condition</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>EnterpriseFilter 接收生成结果</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>applyFilterSnapshot</span></span>
<span class="line"><span>    ├─ 更新当前工作区条件与关系</span></span>
<span class="line"><span>    ├─ DimensionSelector.setValue</span></span>
<span class="line"><span>    │      └─ 配置未就绪 → pendingValue → 配置到达后转换</span></span>
<span class="line"><span>    └─ handleFilterSnapshotSearch(filterData, relation)</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>    生成查询键并选择卡片 / 表格接口</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>    企业结果、分页、保存条件组、分享口令</span></span></code></pre></div><p>请求身份需要单独理解：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>taskId     = 服务端智能搭建任务的身份，可用于页面返回后的任务续接</span></span>
<span class="line"><span>requestId  = 前端某次流连接 / 执行的身份，用于拦截过期回调</span></span>
<span class="line"><span>AbortSignal = 当前连接的取消信号，用于尽量停止不再需要的网络读取</span></span>
<span class="line"><span>queryKey   = 某个结果视图本次查询语义的标识，用于页面内结果复用</span></span></code></pre></div><hr><h2 id="四、最值得深入的五个模块" tabindex="-1">四、最值得深入的五个模块 <a class="header-anchor" href="#四、最值得深入的五个模块" aria-label="Permalink to &quot;四、最值得深入的五个模块&quot;">​</a></h2><h3 id="_1-ai-结果进入既有筛选闭环" tabindex="-1">1. AI 结果进入既有筛选闭环 <a class="header-anchor" href="#_1-ai-结果进入既有筛选闭环" aria-label="Permalink to &quot;1. AI 结果进入既有筛选闭环&quot;">​</a></h3><p><strong>代码证据：</strong> <code>api.js</code> 中的 <code>streamAdvancedFilterAgentBuild</code>、<code>getAdvancedFilterAgentBuildFilter</code>；<code>SmartBuilder/index.js</code> 中对 <code>ready</code> 和条件对象的检查；<code>EnterpriseFilter.js</code> 中的 <code>handleFilterSnapshotSearch</code>。</p><p><strong>为什么值得讲：</strong> 这体现的不是“调用 AI 接口”，而是把不确定的生成过程接入已有的确定性业务流程。生成结果还需要继续被编辑、查询、保存和分享。</p><p><strong>核心设计：</strong> 阶段展示状态、任务完成状态和业务条件可用状态分开判断。只有任务 ready 且条件对象满足基础结构检查时，才进入统一回填入口。</p><p><strong>边界：</strong> 对象存在不等于完整业务校验已经完成；操作符、枚举值、权限仍需要服务端和前端共同保证。当前实现也不能证明具备消息游标级断点续传。</p><h3 id="_2-条件快照与异步回填" tabindex="-1">2. 条件快照与异步回填 <a class="header-anchor" href="#_2-条件快照与异步回填" aria-label="Permalink to &quot;2. 条件快照与异步回填&quot;">​</a></h3><p><strong>代码证据：</strong> <code>utils.js</code> 中的 <code>resolveWorkspaceFilter</code>、<code>pickFilterSnapshot</code>、<code>applyFilterSnapshot</code>；<code>DimensionSelector/index.js</code> 中的 <code>pendingValue</code>、<code>setValue</code> 和配置更新逻辑。</p><p><strong>为什么值得讲：</strong> 条件回填同时影响容器状态、筛选器内部状态和查询参数。只依赖某个组件“当前最新 state”，容易把不同时间点的数据混在一起。</p><p><strong>核心设计：</strong> 用工作区分离普通条件和智能条件；用快照统一更新展示和查询；配置没准备好时先暂存原始条件，配置到达后再转换。</p><p><strong>边界：</strong> 这是针对配置时序和状态归属的处理，不等于建立了完整事务，也不等于所有异步竞态都已消除。</p><h3 id="_3-普通筛选与智能搭建的工作区隔离" tabindex="-1">3. 普通筛选与智能搭建的工作区隔离 <a class="header-anchor" href="#_3-普通筛选与智能搭建的工作区隔离" aria-label="Permalink to &quot;3. 普通筛选与智能搭建的工作区隔离&quot;">​</a></h3><p><strong>代码证据：</strong> <code>resolveWorkspaceFilter</code> 根据 <code>isSmartBuild</code> 读取普通工作区或 <code>smartBuild</code> 工作区；<code>EnterpriseFilter</code> 保存当前条件、模式和查询结果；用户存储按用户保存高级筛选数据。</p><p><strong>为什么值得讲：</strong> 用户可能先配置普通筛选，再进入智能搭建；如果两套条件共用一个可变对象，切换模式时容易覆盖用户正在编辑的内容。</p><p><strong>核心设计：</strong> 把条件归属和模式状态作为独立维度保存。嵌入场景还可以通过 <code>suppressSmartCache</code> 关闭智能条件缓存恢复。</p><p><strong>边界：</strong> 代码证明了工作区分仓和缓存读取路径，不能据此声称所有状态都由 Redux 统一管理；结果、分页和 loading 主要位于页面本地 state。</p><h3 id="_4-卡片-表格双视图与查询协调" tabindex="-1">4. 卡片 / 表格双视图与查询协调 <a class="header-anchor" href="#_4-卡片-表格双视图与查询协调" aria-label="Permalink to &quot;4. 卡片 / 表格双视图与查询协调&quot;">​</a></h3><p><strong>代码证据：</strong> <code>EnterpriseFilter</code> 中的 <code>tableData</code>、<code>cardData</code>、<code>loading</code>、<code>cardLoading</code>、分页字段、<code>getCardSearchKey</code>、<code>getTableSearchKey</code>、<code>pendingFilterSearch</code> 和 <code>componentDidUpdate</code>。</p><p><strong>为什么值得讲：</strong> 两种视图接口和分页语义不同。简单做法是切换视图就重新请求，或者让两个视图共用 loading 和结果，都会增加重复请求或状态相互覆盖的风险。</p><p><strong>核心设计：</strong> 两个结果槽分别维护数据和查询键；查询键包含条件、关系、分页、排序和模式；请求忙碌期间只保留最新待查询条件，结束后继续查询。</p><p><strong>边界：</strong> 这是页面内的结果复用，不是带 TTL 的通用请求缓存，也不是 FIFO 操作队列。查询键匹配只说明请求参数语义一致，不代表服务端数据一定仍然新鲜。</p><h3 id="_5-任务恢复与流连接失效" tabindex="-1">5. 任务恢复与流连接失效 <a class="header-anchor" href="#_5-任务恢复与流连接失效" aria-label="Permalink to &quot;5. 任务恢复与流连接失效&quot;">​</a></h3><p><strong>代码证据：</strong> <code>SmartBuilder/index.js</code> 中的 <code>requestIdRef</code>、<code>abortControllerRef</code>、<code>shouldCancel</code>、卸载清理和恢复逻辑；<code>taskSession.js</code> 中按用户和主体读写任务、五分钟有效期和清理逻辑。</p><p><strong>为什么值得讲：</strong> 页面生命周期和服务端任务生命周期可能不同。页面离开会导致浏览器连接结束，但后端任务未必已经结束。</p><p><strong>核心设计：</strong> 保存任务身份和阶段快照，返回时用原 <code>taskId</code> 重新连接；通过 <code>requestId</code> 拦截旧回调，通过 <code>AbortController</code> 取消旧流；嵌入场景禁用页面级任务恢复。</p><p><strong>边界：</strong> 这是任务级恢复，不是消息游标级断点续传；也不能仅凭前端 abort 证明服务端任务被取消。外部结果回填分支是否覆盖所有旧回调边界，仍需要运行验证。</p><hr><h2 id="五、before-after" tabindex="-1">五、Before / After <a class="header-anchor" href="#五、before-after" aria-label="Permalink to &quot;五、Before / After&quot;">​</a></h2><p>这里的 Before 分为两类：源码没有保留的历史实现不能当作事实；下面“简单替代方案”是为了说明设计权衡的合理推演。</p><h3 id="场景一-ai-结果回填筛选器" tabindex="-1">场景一：AI 结果回填筛选器 <a class="header-anchor" href="#场景一-ai-结果回填筛选器" aria-label="Permalink to &quot;场景一：AI 结果回填筛选器&quot;">​</a></h3><p><strong>简单替代方案：</strong> 收到 AI 结果后直接 <code>setState</code>，再从组件当前 state 读取条件发起查询。</p><p><strong>可能的问题：</strong> React 状态更新和筛选器内部配置转换不一定在同一时刻完成；查询可能读取旧条件，或者配置尚未加载时把条件转换成空值。</p><p><strong>当前实现：</strong> <code>applyFilterSnapshot</code> 同时接收条件和关系，更新容器并驱动 <code>DimensionSelector</code>；查询入口直接使用这次传入的快照。配置未到时由 <code>pendingValue</code> 暂存。</p><p><strong>可以确认的变化：</strong> 生成结果有明确的回填入口，配置晚到有明确的等待位置，回填和查询使用同一份输入。</p><h3 id="场景二-卡片与表格来回切换" tabindex="-1">场景二：卡片与表格来回切换 <a class="header-anchor" href="#场景二-卡片与表格来回切换" aria-label="Permalink to &quot;场景二：卡片与表格来回切换&quot;">​</a></h3><p><strong>简单替代方案：</strong> 两个视图共用一套结果和 loading，切换时无条件重新请求。</p><p><strong>可能的问题：</strong> 卡片和表格的分页、排序、接口字段不同；切换时可能覆盖彼此的 loading 或结果，且相同条件下产生重复请求。</p><p><strong>当前实现：</strong> 两个视图分别保存结果、分页、loading、查询标记和查询键；命中相同查询键时复用对应结果。</p><p><strong>可以确认的变化：</strong> 页面具备该场景下的结果复用和状态隔离路径；没有证据支持“所有请求都已去重”或“数据始终实时”。</p><h3 id="场景三-用户离开后返回" tabindex="-1">场景三：用户离开后返回 <a class="header-anchor" href="#场景三-用户离开后返回" aria-label="Permalink to &quot;场景三：用户离开后返回&quot;">​</a></h3><p><strong>简单替代方案：</strong> 离开页面就丢弃流，返回后重新创建一个任务。</p><p><strong>可能的问题：</strong> 长任务可能被重复创建；用户看不到已经完成的阶段；如果服务端任务仍在运行，前端与服务端任务会失去关联。</p><p><strong>当前实现：</strong> 普通页面保存 <code>taskId</code>、输入、开始时间和阶段快照，五分钟内返回时续接原任务；恢复时跳过已完成阶段。嵌入场景关闭这套缓存。</p><p><strong>可以确认的变化：</strong> 页面返回存在任务级续接路径；恢复范围和嵌入场景边界是明确的。</p><hr><h2 id="六、star-面试回答" tabindex="-1">六、STAR 面试回答 <a class="header-anchor" href="#六、star-面试回答" aria-label="Permalink to &quot;六、STAR 面试回答&quot;">​</a></h2><h3 id="s-背景与问题" tabindex="-1">S：背景与问题 <a class="header-anchor" href="#s-背景与问题" aria-label="Permalink to &quot;S：背景与问题&quot;">​</a></h3><p>企业高级筛选页面本身已经有较多条件维度、条件组合、保存和结果操作。新增智能搭建后，用户可以输入自然语言，但 AI 生成是流式长任务，筛选器配置又是异步加载的，同时页面还支持普通筛选、卡片视图和表格视图。多个状态如果没有明确归属，就可能出现条件显示和实际查询不一致、切换视图重复请求或离开页面后任务无法继续的问题。</p><h3 id="t-职责与目标" tabindex="-1">T：职责与目标 <a class="header-anchor" href="#t-职责与目标" aria-label="Permalink to &quot;T：职责与目标&quot;">​</a></h3><p>我的目标是参与完成智能搭建结果与既有高级筛选系统的衔接，让生成条件能够被筛选器正确回填，并继续支持企业查询、手工调整、保存条件组和分享。同时需要处理流连接取消、页面返回任务恢复以及不同宿主的生命周期差异。</p><p>这里“我独立设计了全部架构”这一表述需要本人确认。当前源码只能证明这些机制存在，不能单独证明每一处都是我提出或独立完成的。</p><h3 id="a-技术方案与落地" tabindex="-1">A：技术方案与落地 <a class="header-anchor" href="#a-技术方案与落地" aria-label="Permalink to &quot;A：技术方案与落地&quot;">​</a></h3><ol><li>在流接口层使用 POST Fetch 接收 SSE，增量解码并按空行拆分事件，区分阶段、ready 结果、错误和异常断流。</li><li>任务 ready 后先检查可用条件对象，再通过 <code>applyFilterSnapshot</code> 统一回填容器和筛选器。</li><li>配置未到时用 <code>pendingValue</code> 保存待转换条件，配置到达后优先恢复这份值，并单独处理关系值 0 和 1。</li><li>普通工作区和智能搭建工作区分别保存条件；卡片和表格分别保存结果、分页和 loading。</li><li>用查询键判断页面内结果是否可复用；请求忙碌时只保留最新一份待查询条件。</li><li>用 <code>taskId</code> 关联服务端任务，用 <code>requestId</code> 判断前端执行是否过期，用 <code>AbortController</code> 取消旧连接；普通页面保存限时任务快照，嵌入页面禁用缓存恢复。</li></ol><h3 id="r-结果与复盘" tabindex="-1">R：结果与复盘 <a class="header-anchor" href="#r-结果与复盘" aria-label="Permalink to &quot;R：结果与复盘&quot;">​</a></h3><p>从代码上可以确认，项目形成了自然语言输入、流式进度、条件回填、企业查询、人工编辑、保存条件组和分享口令的完整链路；也形成了配置晚到、视图切换和页面返回等场景的处理路径。</p><p>当前没有可直接引用的线上耗时、请求量、恢复成功率或用户效率指标，所以我不会编造百分比。下一步可以通过固定条件下的请求计数、任务恢复成功率、配置与结果不同到达顺序的用例，以及旧请求乱序回写测试来验证收益。</p><hr><h2 id="七、高频追问与背诵答案" tabindex="-1">七、高频追问与背诵答案 <a class="header-anchor" href="#七、高频追问与背诵答案" aria-label="Permalink to &quot;七、高频追问与背诵答案&quot;">​</a></h2><h3 id="_1-这个项目和普通-crud-项目的主要区别是什么" tabindex="-1">1. 这个项目和普通 CRUD 项目的主要区别是什么？ <a class="header-anchor" href="#_1-这个项目和普通-crud-项目的主要区别是什么" aria-label="Permalink to &quot;1. 这个项目和普通 CRUD 项目的主要区别是什么？&quot;">​</a></h3><p>普通 CRUD 主要围绕一次请求、一次响应和表单状态展开。这个项目有多个持续变化的状态：AI 流式任务、筛选条件草稿、已提交查询、卡片和表格结果、页面缓存以及用户编辑行为。难点是定义每个状态属于谁、什么时候可以提交、旧结果什么时候必须失效，而不只是把接口调用出来。</p><h3 id="_2-为什么不能拿到-ai-总结文案后就直接搜索" tabindex="-1">2. 为什么不能拿到 AI 总结文案后就直接搜索？ <a class="header-anchor" href="#_2-为什么不能拿到-ai-总结文案后就直接搜索" aria-label="Permalink to &quot;2. 为什么不能拿到 AI 总结文案后就直接搜索？&quot;">​</a></h3><p>总结文案只是展示内容，不一定是结构化、合法、可查询的条件。当前实现会检查任务状态是否为 ready，并通过 <code>getAdvancedFilterAgentBuildFilter</code> 检查条件对象的基础结构，然后才进入筛选器回填。完整的字段、操作符和权限校验仍然需要服务端和业务规则共同保证。</p><h3 id="_3-为什么要使用条件快照" tabindex="-1">3. 为什么要使用条件快照？ <a class="header-anchor" href="#_3-为什么要使用条件快照" aria-label="Permalink to &quot;3. 为什么要使用条件快照？&quot;">​</a></h3><p>因为一次操作包含多个异步更新：容器要更新条件，筛选器要把接口格式转换成内部结构，查询又不能依赖某个时刻恰好读取到的可变 state。快照把“本次用户确认的条件”作为显式参数同时传给回填和查询，减少状态更新时序造成的隐式依赖。</p><h3 id="_4-setstate-的回调已经执行了-为什么还需要快照" tabindex="-1">4. <code>setState</code> 的回调已经执行了，为什么还需要快照？ <a class="header-anchor" href="#_4-setstate-的回调已经执行了-为什么还需要快照" aria-label="Permalink to &quot;4. \`setState\` 的回调已经执行了，为什么还需要快照？&quot;">​</a></h3><p><code>setState</code> 回调只能说明当前组件这次更新完成，不能说明另一个筛选器组件的配置已经完成，也不能保证后续读取的 state 仍然代表这次操作。快照解决的是查询输入的明确归属，<code>pendingValue</code> 解决的是筛选配置尚未就绪，两者处理的是不同层次的问题。</p><h3 id="_5-pendingvalue-解决了什么问题" tabindex="-1">5. <code>pendingValue</code> 解决了什么问题？ <a class="header-anchor" href="#_5-pendingvalue-解决了什么问题" aria-label="Permalink to &quot;5. \`pendingValue\` 解决了什么问题？&quot;">​</a></h3><p><code>DimensionSelector</code> 需要配置才能把服务端条件转换为内部的维度结构。如果条件先到而配置后到，立即转换可能得到空条件，后续默认值还可能覆盖它。代码在配置缺失时先暂存传入值，配置到达后优先消费 <code>pendingValue</code>，再执行转换。这个机制解决的是“配置与条件到达顺序不同”的问题。</p><h3 id="_6-为什么普通筛选和智能搭建要分开保存" tabindex="-1">6. 为什么普通筛选和智能搭建要分开保存？ <a class="header-anchor" href="#_6-为什么普通筛选和智能搭建要分开保存" aria-label="Permalink to &quot;6. 为什么普通筛选和智能搭建要分开保存？&quot;">​</a></h3><p>它们是两个不同的用户工作区。用户可能在普通筛选里已经编辑了一组条件，再尝试智能搭建；如果共用一份条件，就需要额外处理覆盖和恢复。当前实现通过 <code>resolveWorkspaceFilter</code> 区分普通条件和 <code>smartBuild</code> 条件，页面缓存也按用户读取对应工作区。</p><h3 id="_7-为什么卡片和表格要分别保存结果" tabindex="-1">7. 为什么卡片和表格要分别保存结果？ <a class="header-anchor" href="#_7-为什么卡片和表格要分别保存结果" aria-label="Permalink to &quot;7. 为什么卡片和表格要分别保存结果？&quot;">​</a></h3><p>两种视图使用的接口、字段、分页和排序语义不同。分别保存结果和 loading 可以避免切换视图时相互覆盖。查询键则进一步判断当前结果是否对应同一组条件、分页、排序和模式。它是页面内的结果复用，不是通用缓存系统。</p><h3 id="_8-请求进行中用户再次点击筛选-为什么只保存最新一次" tabindex="-1">8. 请求进行中用户再次点击筛选，为什么只保存最新一次？ <a class="header-anchor" href="#_8-请求进行中用户再次点击筛选-为什么只保存最新一次" aria-label="Permalink to &quot;8. 请求进行中用户再次点击筛选，为什么只保存最新一次？&quot;">​</a></h3><p>当前实现选择的是“最新意图优先”。用户连续修改条件时，中间每一次条件通常没有必要都执行；保留完整 FIFO 队列反而可能让页面继续执行用户已经放弃的条件。代价是中间操作不会逐个执行，而且它只覆盖了 <code>handleFilter</code> 这条入口，其他直接取数入口仍需要单独验证。</p><h3 id="_9-为什么用-post-fetch-sse-而不是原生-eventsource" tabindex="-1">9. 为什么用 POST Fetch SSE，而不是原生 EventSource？ <a class="header-anchor" href="#_9-为什么用-post-fetch-sse-而不是原生-eventsource" aria-label="Permalink to &quot;9. 为什么用 POST Fetch SSE，而不是原生 EventSource？&quot;">​</a></h3><p>这个接口需要提交自然语言输入和可选的 <code>taskId</code>，使用 POST 更符合请求协议；同时前端需要传递鉴权信息、接入 <code>AbortController</code> 并处理非 2xx 响应。原生 EventSource 更适合固定 URL 的单向订阅，对请求体和取消控制不够灵活。Fetch + ReadableStream 的代价是需要自己处理增量解码、分帧、错误和结束状态。</p><h3 id="_10-taskid、requestid-和-abortcontroller-分别解决什么问题" tabindex="-1">10. <code>taskId</code>、<code>requestId</code> 和 <code>AbortController</code> 分别解决什么问题？ <a class="header-anchor" href="#_10-taskid、requestid-和-abortcontroller-分别解决什么问题" aria-label="Permalink to &quot;10. \`taskId\`、\`requestId\` 和 \`AbortController\` 分别解决什么问题？&quot;">​</a></h3><p><code>taskId</code> 是服务端任务身份，用于页面返回后继续连接同一个任务；<code>requestId</code> 是前端本次执行身份，用于判断回调是否仍属于当前执行；<code>AbortController</code> 用于取消旧的网络读取。取消连接负责释放资源，执行序号负责阻止过期结果写入，服务端任务是否终止还要看后端协议。</p><h3 id="_11-这是不是断点续传" tabindex="-1">11. 这是不是断点续传？ <a class="header-anchor" href="#_11-这是不是断点续传" aria-label="Permalink to &quot;11. 这是不是断点续传？&quot;">​</a></h3><p>只能称为任务级恢复，不能直接称为消息级断点续传。当前实现保存任务 ID 和阶段快照，返回页面后重新连接同一个任务，并跳过已经完成的阶段。没有足够证据证明保存了每条消息的游标、服务端支持事件重放，也没有证明任意断网都能自动恢复。</p><h3 id="_12-如果没有这套实现-项目会是什么状态" tabindex="-1">12. 如果没有这套实现，项目会是什么状态？ <a class="header-anchor" href="#_12-如果没有这套实现-项目会是什么状态" aria-label="Permalink to &quot;12. 如果没有这套实现，项目会是什么状态？&quot;">​</a></h3><p>历史旧实现需要以提交记录或当时的代码为依据，当前不能断言过去一定存在某个缺陷。作为简单替代方案，如果只在收到结果后直接更新 state 并查询，配置晚到、状态切换和查询输入归属会更依赖调用时序；如果切换视图始终重新请求，可能增加同条件下的重复请求。当前代码提供了快照、待回填、查询键和任务恢复这些明确路径，但收益仍应通过测试和业务数据验证。</p><h3 id="_13-你个人具体做了什么" tabindex="-1">13. 你个人具体做了什么？ <a class="header-anchor" href="#_13-你个人具体做了什么" aria-label="Permalink to &quot;13. 你个人具体做了什么？&quot;">​</a></h3><p>保守回答可以是：我主要参与高级筛选与智能搭建相关的前端开发，重点关注生成结果如何进入既有筛选链路、异步回填和任务状态处理。具体哪些函数是我独立设计或修改的，需要结合提交记录和实际经历确认。代码能够证明方案和机制存在，但不能单独证明个人归属。</p><p>确认个人职责后，可以把这段改成：我负责……，我发现……，我选择……，最后通过……验证……。如果没有亲自参与的部分，就保留“项目采用”“我参与联调”这样的表述。</p><h3 id="_14-这个方案还有哪些不足" tabindex="-1">14. 这个方案还有哪些不足？ <a class="header-anchor" href="#_14-这个方案还有哪些不足" aria-label="Permalink to &quot;14. 这个方案还有哪些不足？&quot;">​</a></h3><p>第一，查询结果回写没有在所有路径统一使用 generation 校验，重叠请求下旧 success、error 或 finally 是否会影响新请求，需要运行验证。第二，任务恢复不是消息游标级恢复。第三，条件对象的基础结构检查不等于完整 schema 校验。第四，页面本地状态、筛选器内部状态和缓存之间仍有同步成本。第五，查询键没有 TTL 语义，不能保证服务端数据实时。</p><hr><h2 id="八、面试官三级追问" tabindex="-1">八、面试官三级追问 <a class="header-anchor" href="#八、面试官三级追问" aria-label="Permalink to &quot;八、面试官三级追问&quot;">​</a></h2><h3 id="主题一-条件一致性" tabindex="-1">主题一：条件一致性 <a class="header-anchor" href="#主题一-条件一致性" aria-label="Permalink to &quot;主题一：条件一致性&quot;">​</a></h3><p><strong>第一层：</strong> AI 结果是怎么显示到筛选器里的？</p><p>答：任务 ready 后取得结构化条件，进入 <code>applyFilterSnapshot</code>，由它更新容器状态并调用 <code>DimensionSelector.setValue</code>。</p><p><strong>第二层：</strong> 为什么不直接调用筛选器的 <code>setValue</code>？</p><p>答：只更新筛选器会让容器条件、查询条件和筛选器展示之间缺少统一入口。<code>applyFilterSnapshot</code> 先明确本次条件和关系，再决定只回填还是同时查询。</p><p><strong>第三层：</strong> 条件先到、配置后到、用户又手工修改时，谁应该优先？</p><p>答：当前代码明确处理了配置未到时的 <code>pendingValue</code>，但用户编辑与异步结果之间的完整优先级规则需要结合实际产品约定和运行用例确认。更成熟的做法是给每次回填和用户编辑增加版本或 dirty 标记，明确旧结果是否还能覆盖用户输入。</p><h3 id="主题二-查询复用" tabindex="-1">主题二：查询复用 <a class="header-anchor" href="#主题二-查询复用" aria-label="Permalink to &quot;主题二：查询复用&quot;">​</a></h3><p><strong>第一层：</strong> 你们缓存了什么？</p><p>答：页面内缓存的是不同结果视图已经完成的结果和查询元信息，通过查询键判断是否可以复用。</p><p><strong>第二层：</strong> 查询键包含哪些内容？</p><p>答：当前代码将条件、关系、分页、排序、业务排序和模式等信息组合成键。它表达查询语义，不代表数据有 TTL 或一定新鲜。</p><p><strong>第三层：</strong> A 请求慢、B 请求快、A 最后返回怎么办？</p><p>答：这是当前需要重点验证的边界。<code>pendingFilterSearch</code> 处理的是筛选提交期间的最新意图，但所有结果请求的 success、error、finally 是否统一校验请求代次，当前材料没有证明完全覆盖。若要强化，应为每个结果槽引入 generation，所有写入和清理都验证请求归属。</p><h3 id="主题三-任务恢复" tabindex="-1">主题三：任务恢复 <a class="header-anchor" href="#主题三-任务恢复" aria-label="Permalink to &quot;主题三：任务恢复&quot;">​</a></h3><p><strong>第一层：</strong> 离开页面后怎么恢复？</p><p>答：普通页面保存用户和主体对应的 <code>taskId</code>、输入、开始时间和阶段快照，五分钟内返回时带着原任务 ID 重新连接。</p><p><strong>第二层：</strong> 为什么还需要 <code>requestId</code>？</p><p>答：恢复同一个服务端任务也会产生新的前端连接，所以必须为这次连接创建新的执行身份。<code>requestId</code> 防止旧连接或旧展示队列回写当前界面。</p><p><strong>第三层：</strong> 如果旧 Promise 已经完成，只是后续展示动画还没结束，abort 能阻止它吗？</p><p>答：不能保证。abort 主要作用于网络读取，已经完成的 Promise 链和展示队列仍可能继续执行，所以还需要在每个关键回调提交前检查当前执行身份。当前外部结果回填分支的失效边界需要通过测试进一步确认。</p><h3 id="主题四-技术选型" tabindex="-1">主题四：技术选型 <a class="header-anchor" href="#主题四-技术选型" aria-label="Permalink to &quot;主题四：技术选型&quot;">​</a></h3><p><strong>第一层：</strong> 为什么是 SSE？</p><p>答：一次用户输入对应一个服务端任务，任务期间主要由服务端向前端持续推送阶段和结果事件，SSE 的通信方向符合当前场景。</p><p><strong>第二层：</strong> 为什么不用 WebSocket？</p><p>答：当前不需要连接上的高频双向通信，WebSocket 会引入更复杂的连接和消息协议管理。若未来变成实时双向协作，再重新评估。</p><p><strong>第三层：</strong> 自己解析 SSE 的代价是什么？</p><p>答：需要正确处理字节跨块、字符跨块、事件跨块、空行分帧、多行 data、异常响应和无终态断流；成熟库可以降低协议维护成本，但仍要核对它与后端业务事件的契约。当前解析器面向项目业务 data，不能包装成完整的标准 SSE 客户端。</p><hr><h2 id="九、贡献证据与可信程度" tabindex="-1">九、贡献证据与可信程度 <a class="header-anchor" href="#九、贡献证据与可信程度" aria-label="Permalink to &quot;九、贡献证据与可信程度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>贡献</th><th>代码证据</th><th>个人职责</th><th>Before</th><th>After</th><th>可信程度</th></tr></thead><tbody><tr><td>将 AI 结果接入筛选闭环</td><td><code>streamAdvancedFilterAgentBuild</code>、<code>getAdvancedFilterAgentBuildFilter</code>、<code>applyFilterSnapshot</code></td><td>需要确认是独立实现、参与开发还是联调</td><td>AI 结果无法直接作为普通筛选输入；历史情况缺少证据</td><td>ready 条件进入统一回填、查询、保存和分享路径</td><td>代码高；个人归属待确认</td></tr><tr><td>异步配置下的条件回填</td><td><code>DimensionSelector.pendingValue</code>、配置到达后的转换逻辑</td><td>需要确认是否由本人发现和修改</td><td>简单实现可能在配置缺失时提前转换；历史旧行为缺少证据</td><td>条件先到时暂存，配置到达后优先回填</td><td>代码高；历史对比待确认</td></tr><tr><td>普通 / 智能工作区隔离</td><td><code>resolveWorkspaceFilter</code>、用户存储和 <code>smartBuild</code> 字段</td><td>需要确认是否参与状态建模</td><td>共用条件会增加模式切换覆盖风险；属于合理推演</td><td>两类条件按工作区保存，嵌入场景可关闭恢复</td><td>代码高；个人归属待确认</td></tr><tr><td>卡片 / 表格结果复用</td><td>双视图 state、<code>getCardSearchKey</code>、<code>getTableSearchKey</code></td><td>需要确认是否参与查询协调设计</td><td>无条件切换可能重复请求；历史实现缺少证据</td><td>同键结果可复用，忙碌时保留最新查询</td><td>代码高；线上收益缺少指标</td></tr><tr><td>任务级恢复和前端流隔离</td><td><code>taskSession.js</code>、<code>requestIdRef</code>、<code>AbortController</code></td><td>需要确认负责范围和联调过程</td><td>离开后重新创建任务是简单替代方案</td><td>五分钟内可续接原任务，旧连接回调受拦截</td><td>代码高；恢复成功率缺少指标</td></tr></tbody></table><hr><h2 id="十、不能主动说过头的地方" tabindex="-1">十、不能主动说过头的地方 <a class="header-anchor" href="#十、不能主动说过头的地方" aria-label="Permalink to &quot;十、不能主动说过头的地方&quot;">​</a></h2><ul><li>不说“我从零设计了整套高级筛选架构”，除非有提交记录或明确的技术方案证据。</li><li>不说“解决了所有竞态”，当前查询结果回写和外部回填仍有待验证边界。</li><li>不说“实现了断点续传”，当前更准确的是“任务级恢复”。</li><li>不说“Redux 管理了全部状态”，结果、分页和 loading 主要在页面本地 state。</li><li>不说“实现了全局请求缓存”，当前是页面内按查询键复用结果。</li><li>不说“AI 条件已经完成完整校验”，当前源码能确认的是 ready 和条件对象的基础检查。</li><li>不说“效率提升了百分之多少”，除非能拿出埋点、日志或对比实验。</li><li>不把模型生成算法、Prompt 设计和服务端任务执行归为前端个人贡献。</li></ul><hr><h2 id="十一、面试前只需要补齐的事实" tabindex="-1">十一、面试前只需要补齐的事实 <a class="header-anchor" href="#十一、面试前只需要补齐的事实" aria-label="Permalink to &quot;十一、面试前只需要补齐的事实&quot;">​</a></h2><p>这些问题按优先级排列，下一轮只先回答第一个：</p><ol><li><strong>在这个项目中，智能搭建、<code>pendingValue</code> 回填、查询协调这几部分里，哪些代码是你亲自设计或修改的？请尽量说出一个具体文件或函数。</strong></li><li>需求是产品提出、后端提出，还是你主动发现并推动的？</li><li>当时有没有遇到真实线上问题、用户反馈或联调故障？</li><li>有没有被否决过的方案？为什么没有采用？</li><li>你用什么方式验证过配置先后顺序、视图切换和任务恢复？</li><li>是否有请求量、恢复成功率、操作耗时或重复请求数等可引用数据？</li></ol><p>收到第一个问题的答案后，再把口述稿中的“我参与”“项目采用”替换成准确的个人职责表达。</p>`,161)])])}const u=a(s,[["render",r]]);export{g as __pageData,u as default};
